WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY segment ORDER BY age ASC NULLS LAST, id ASC) AS rn FROM customers QUALIFY rn = 1) SELECT city, CASE WHEN credit_limit >= 16300 THEN 'HIGH' ELSE 'LOW' END AS credit_limit_tier, ROUND(SUM(credit_limit) / NULLIF(COUNT(CASE WHEN country = 'DE' THEN 1 END), 0), 2) AS credit_limit_per_de, COUNT(CASE WHEN segment = 'Consumer' THEN 1 END) AS consumer_count, BIT_AND(age) AS age_bit_and, APPROX_PERCENTILE(age, 0.9) AS age_p90 FROM deduped GROUP BY 1, 2 ORDER BY consumer_count ASC NULLS LAST
